/// Why a publish was rejected after it was accepted (`PublishStatus`).
/// Not an HTTP error. Clients treat an unknown value as a generic rejection.
pub const RejectionCode = enum {
    archive_invalid,
    path_not_allowed,
    limit_exceeded,
    manifest_invalid,
    filename_mismatch,
    sha256_mismatch,
    dependency_not_allowed,
    /// A value this client does not know.
    unknown,

    pub fn jsonParse(a: Allocator, source: anytype, options: std.json.ParseOptions) std.json.ParseError(@TypeOf(source.*))!RejectionCode {
        const value = try std.json.innerParse(std.json.Value, a, source, options);
        return jsonParseFromValue(a, value, options);
    }

    pub fn jsonParseFromValue(_: Allocator, value: std.json.Value, _: std.json.ParseOptions) std.json.ParseFromValueError!RejectionCode {
        switch (value) {
            .string => |s| return std.meta.stringToEnum(RejectionCode, s) orelse .unknown,
            else => return error.UnexpectedToken,
        }
    }

    pub fn jsonStringify(self: RejectionCode, jw: anytype) !void {
        try jw.write(@tagName(self));
    }
};

pub const Health = struct {
    status: HealthStatus,
