    name: FullName,
    /// Optional, member by member, with the meaning it has in `CommitPublishRequest`. A repeated commit must repeat which members gave it and what they gave, or it is another request (`group_commit_refused`).
    manifest_sha256: ?Sha256 = null,
    /// Optional, member by member, with the meaning it has in `CommitPublishRequest`. It is stored on that member's version only, and is part of the request a repeated commit must repeat.
    source_commit: ?SourceCommit = null,
    /// As in `CommitPublishRequest`.
    description: ?[]const u8 = null,
    /// As in `CommitPublishRequest`.
    license: ?[]const u8 = null,
    /// An https URL.
    repository: ?[]const u8 = null,
    /// An https URL.
    homepage: ?[]const u8 = null,
    keywords: ?Keywords = null,
    /// Either the text of the readme (a string: untrusted Markdown of at most 64 KiB, as in `CommitPublishRequest`) or,
    /// at a registry that lists `group_readme_objects` in the `features` of `getHealth`, a `ReadmeRef` of a readme the
    /// caller PUT to the URL `createGroup` gave for it.
    ///
    /// The registry reads the object once the group's files are checked and before it stores anything. An object
    /// that is not in storage, or whose bytes differ in length or SHA-256 from the reference, is `upload_invalid`
    /// and names the member; bytes that are not UTF-8 text, or a reference that is not well formed, are
    /// `invalid_request` and name the member. Either refusal leaves the group `open`. The text read is then handled as
    /// an inline readme is (the same limits, the same sanitising rules, a leading byte order mark kept), so the
    /// version that results is the same as one committed with the text.
    ///
    /// A repeated commit must repeat the form of each member's readme: the string and the object are different
    /// requests, and a repeat in the other form is `group_commit_refused`. The comparison of a repeat reads no object.
    ///
    /// A registry from before `group_readme_objects` refuses a readme that is not a string with `invalid_request`,
    /// and the group stays `open`, so a client can send the text instead.
    readme: ?CommitGroupMemberReadme = null,
};

pub const CommitGroupMemberReadme = union(enum) {
    text: []const u8,
    object: ReadmeRef,

    pub fn jsonParse(a: Allocator, source: anytype, options: std.json.ParseOptions) std.json.ParseError(@TypeOf(source.*))!CommitGroupMemberReadme {
        const value = try std.json.innerParse(std.json.Value, a, source, options);
