/// Returns a user code to show the person and a device code to poll with.
/// The approval page shows the requesting client and expires in ten
/// minutes. Throttled per IP and per device code.
pub const StartDeviceLogin = struct {
    pub const operation_id = "startDeviceLogin";
    pub const method: std.http.Method = .POST;
    pub const path_template = "/auth/device";
    pub const success = [_]u16{200};
    pub const Params = StartDeviceLoginParams;
    pub const Response = DeviceStartResponse;

    pub fn target(arena: Allocator, _: Params) Allocator.Error![]const u8 {
        var out = std.ArrayList(u8).init(arena);
        const w = out.writer();
        try w.writeAll("/auth/device");
        return out.toOwnedSlice();
    }

    pub fn body(arena: Allocator, p: Params) Allocator.Error!?[]const u8 {
        return try std.json.stringifyAlloc(arena, p.body, .{ .emit_null_optional_fields = false });
    }
};

/// Poll no faster than `interval` seconds. While the person has not
/// decided, `status` is `pending`. `approved` carries a session token;
/// the session is fresh (see `fresh_until`) so that the CLI can mint an
/// API token right after login.
pub const PollDeviceLogin = struct {
    pub const operation_id = "pollDeviceLogin";
    pub const method: std.http.Method = .POST;
    pub const path_template = "/auth/device/poll";
    pub const success = [_]u16{200};
