/// Filters only what the index serves: a prefix (`q`) and a sort order. `q` is a name prefix, or
/// `<namespace>/` with an optional name prefix to list one namespace's packages. Filtering by platform, Mojo
/// version or native library is not offered.
pub const SearchPackages = struct {
    pub const operation_id = "searchPackages";
    pub const method: std.http.Method = .GET;
    pub const path_template = "/packages";
    pub const success = [_]u16{200};
    pub const Params = SearchPackagesParams;
    pub const Response = PackageList;

    pub fn target(arena: Allocator, p: Params) Allocator.Error![]const u8 {
        var out = std.ArrayList(u8).init(arena);
        const w = out.writer();
        try w.writeAll("/packages");
        var sep: u8 = '?';
        if (p.q) |v| {
            try w.writeByte(sep);
            sep = '&';
            try w.writeAll("q=");
            try percentEncode(w, v);
        }
        if (p.sort) |v| {
            try w.writeByte(sep);
            sep = '&';
            try w.writeAll("sort=");
            try percentEncode(w, @tagName(v));
        }
        if (p.cursor) |v| {
            try w.writeByte(sep);
            sep = '&';
            try w.writeAll("cursor=");
            try percentEncode(w, v);
        }
        if (p.limit) |v| {
            try w.writeByte(sep);
            sep = '&';
            try w.writeAll("limit=");
            try w.print("{d}", .{v});
        }
        return out.toOwnedSlice();
    }

    pub fn body(_: Allocator, _: Params) Allocator.Error!?[]const u8 {
        return null;
    }
};

